#!/bin/sh
# Generate src/generated/v4.rs and src/generated/status.rs from the
# schemas in this folder, with the command that made each at its top.
# The files carry the @generated marker, and .gitattributes marks the
# folder linguist-generated, so tools and reviews can skip them. Run it
# from anywhere after copying new schemas from the Changescape repo
# (skill/src/changescape/contract/).
# Needs cargo-typify 0.8.0: cargo install cargo-typify --version 0.8.0
set -eu
cd "$(dirname "$0")/.."
gen() {
    schema=$1 out=$2
    shift 2
    tmp=$(mktemp) inlined=$(mktemp)
    python3 schema/inline_unions.py "$schema" >"$inlined"
    cargo typify --no-builder "$@" "$inlined" -o "$tmp"
    {
        echo "// @generated by crates/perch-changescape/schema/generate.sh:"
        echo "//   python3 schema/inline_unions.py $schema, then"
        echo "//   cargo typify --no-builder ${*:+$* }<that> -o $out"
        echo "// Do not edit by hand."
        echo
        cat "$tmp"
    } >"$out"
    rm "$tmp" "$inlined"
    rustfmt --edition 2021 "$out"
}
gen schema/page.v4.schema.json src/generated/v4.rs --additional-derive PartialEq
gen schema/status.v4.schema.json src/generated/status.rs --additional-derive PartialEq --additional-derive Eq
